import React,{useEffect,useMemo,useRef,useState} from 'react';
import {CheckoutCharge,CheckoutPerson,OldDebt,SaleProduct,CashSession,checkoutBalance,checkoutCollect,checkoutFamily,checkoutOldDebts,checkoutProducts,checkoutSearch,checkoutSellProduct,cashCurrent,cashOpen,cashClose,cashHistory,cashJournal,cashDaySummary,financeReportTemplates,financeReportPreview,FinanceReportTemplate,financeDecisions,financeResponsibilities,financeCredits,FinanceDecision,FinanceResponsibility,FinanceCredit,feeTrackingTaxonomy,feeTrackingOverview,feeTrackingStudents,FeeTrackingRow,financeHistoryImportTemplate,analyzeFinanceHistoryImport,executeFinanceHistoryImport,paymentOptions,type PaymentOptions} from './api';
const PAY_MODE_LABEL:Record<string,string>={CASH:'Espèces',MOBILE_MONEY:'Mobile Money',BANQUE:'Banque',AUTRE:'Autre'};
import {checkoutPlans,checkoutPlanMembership,checkoutPlanPreview,checkoutCollectPlan,type ApplicablePlan,type PlanPreview,familyCollect,getPrintSettings,printBasketReceipts,printReceipt,type BasketResult,type PrintSettings} from './api';
import {toast} from 'sonner';
import {CashExpenseForm,SchoolDayPanel,useReversal} from './cash_controls';
